"""miner_3 2026-07-30: validate 4 new candidates + re-validate 4 library factors."""
import sys
sys.path.insert(0, "scripts")
import numpy as np
import pandas as pd
from miner3_lib import build_panel, forward_returns, spearman_ic, mean_rank_turnover, ADMISSION_HORIZON

